// with it.
func (s gateTenant) Erase(ctx context.Context, req *apptest.TenantRef) (*apptest.TenantEraseResponse, error) {
	return nil, gate.ErrDeployment("taken down")
}

type gateHolder struct {
	Gate
	apptest.HolderServiceServer
}

func (s Gate) Holder() apptest.HolderServiceServer {
	v := gateHolder{s, s.Next().Holder()}
	v.HolderServiceServer = bare.HolderWithAddRule(v.HolderServiceServer, v.admit)
	return v
}

// admit is the one thing about a holder this layer still says, and it is here
// because it is the one that is not a predicate: the row does not exist yet,
// so there is nothing to narrow. Reading one, changing one and erasing one
// are all the wall.
//
// The check is a read of the tenant **through the wall** rather than a
// comparison against the scope, which costs a query and is worth it. A
// reference names a tenant by identifier or by alias, and answering "is this
// one of mine" without a query means holding every tenant in scope in full --
// fine while that is the caller's own and wrong as soon as it is a list a
// credential or a policy narrowed to.
//
// NotFound and not a refusal, which is the same answer every other read of a
// tenant gives: that one exists is itself something a caller who may not see
// it should not be told. It also gets a tenant that simply is not there
// right, which comparing against a scope did not.
//
// And what an app's overlay added to the holder is asked here with it, as it
// is of the app's own entities: a stamp a request may not assert, and an
// edge, which is a read of whatever it names.
//
// It is what an Add of a holder is asked, and an AddMany of every item it
// carries if the entity had one; see [ruled].
func (s gateHolder) admit(ctx context.Context, req *apptest.HolderAddRequest) (*apptest.HolderAddRequest, error) {
	if _, err := gate.Actor(ctx); err != nil {
		return nil, err
	}

	if req.GetDirectory() != "" {
		return nil, pderr.Invalidf("directory", "is established by this deployment and not asserted by a request")
	}

	if err := seen.Visible(ctx, s.Gate.drv, "Tenant", req.GetTenant(), func() error {
		_, err := s.Gate.Next().Tenant().Get(ctx, apptest.TenantGetRequest_builder{
			Ref: req.GetTenant(),
		}.Build())
		return err
	}); err != nil {
		if status.Code(err) == codes.NotFound {
			return nil, gate.ErrNotFound("Tenant")
		}

		return nil, err
	}

	if ref := req.GetRobot(); ref != nil {
		if err := seen.Visible(ctx, s.Gate.drv, "Robot", ref, func() error {
			_, err := s.Gate.Next().Robot().Get(ctx, apptest.RobotGetRequest_builder{
				Ref: ref,
			}.Build())
			return err
		}); err != nil {
			if status.Code(err) == codes.NotFound {
				return nil, gate.ErrNotFound("Robot")
			}

			return nil, err
		}
	}

	return req, nil
}

// Patch refuses an edge moved onto a row this caller cannot see.
//
// The wall narrows the row being written and says nothing about what the
// write points **at**. An edge is a read -- a `Select` walks it -- so one
// moved out of the caller's scope is a way through the wall one hop later,
// exactly as it would have been at `Add`.
func (s gateHolder) Patch(ctx context.Context, req *apptest.HolderPatchRequest) (*apptest.Holder, error) {
	if ref := req.GetRobot(); ref != nil {
		if err := seen.Visible(ctx, s.Gate.drv, "Robot", ref, func() error {
			_, err := s.Gate.Next().Robot().Get(ctx, apptest.RobotGetRequest_builder{
				Ref: ref,
			}.Build())
			return err
		}); err != nil {
			if status.Code(err) == codes.NotFound {
				return nil, gate.ErrNotFound("Robot")
			}

			return nil, err
		}
	}

	return s.HolderServiceServer.Patch(ctx, req)
}

